"""Source relationships, blocking, the family graph and weak-bridge splitting
(DIP-0C2c).

Families are **derived** from the edge graph as connected components, purely for
review convenience — the edges stay authoritative and are never collapsed away.

Two safety properties:

* **No naive all-pairs.** Candidate pairs are generated by blocking (exact-SHA
  groups, format buckets, aspect buckets, size bands, filename families,
  folder/package groups and pHash banding). Detailed comparison runs only inside
  plausible blocks, and the runner reports pairs-compared vs the naive N².
* **No weak transitive chaining.** A ~ B and B ~ C must not prove A ~ C. Only
  edges at or above `STRONG_EDGE_CONFIDENCE` build components, and an edge that is
  the *sole* connector between two halves of a component (a **bridge**) with
  confidence below `WEAK_BRIDGE_CONFIDENCE` **splits** the component and is
  reported for human review.
"""
from __future__ import annotations

import re
from collections import defaultdict
from pathlib import Path

from . import config as C
from . import relationships as R

PARSER = f"{C.TOOL_NAME}.families/{C.TOOL_VERSION}"

_VERSION_SUFFIX = re.compile(
    r"[-_ ]*(\(\d+\)|v\d+|copy|final|rev\d*|\d+)$", re.I)


def normalize_stem(name: str) -> str:
    stem = Path(name).stem
    prev = None
    while prev != stem:
        prev = stem
        stem = _VERSION_SUFFIX.sub("", stem).strip()
    return stem.lower()


# --- source-level graph -----------------------------------------------------
def _perceptual_corroboration(a: dict, b: dict) -> dict | None:
    """Whole-SOURCE visual comparison, attached to a structural source edge as
    corroborating evidence.

    This exists because a visual family link can be real while being invisible at
    candidate level: when one source is segmented into many crops and another is a
    single whole-file candidate, no candidate pair is comparable (a sticker is not
    the whole sheet). The link is still true of the FILES, so it is recorded here —
    as evidence on a structural edge, never as candidate equivalence.
    """
    from . import phash
    ha, hb = a.get("hash"), b.get("hash")
    if not ha or not hb:
        return None
    best = (None, 64, 64)
    for xf, v in hb["variants"].items():
        dd = phash.hamming(ha["dhash"], v["dhash"])
        dp = phash.hamming(ha["phash"], v["phash"])
        if max(dd, dp) < max(best[1], best[2]):
            best = (xf, dd, dp)
    xf, dd, dp = best
    weak = (ha["information"]["weak_evidence"] or hb["information"]["weak_evidence"])
    near = (dd <= C.HAMMING_STRONG and dp <= C.HAMMING_STRONG and not weak)
    return {"best_transform": xf, "dhash_distance": dd, "phash_distance": dp,
            "visually_near_identical": near,
            "weak_visual_evidence": weak,
            "transform_only": near and xf != C.XF_IDENTITY}


def source_edges(sources: list[dict]) -> list[dict]:
    """`sources`: [{relative_path, sha256, format, folder, filename, hash}]"""
    edges: list[dict] = []

    by_sha = defaultdict(list)
    for s in sources:
        if s.get("sha256"):
            by_sha[s["sha256"]].append(s)
    for sha, group in by_sha.items():
        paths = {g["relative_path"] for g in group}
        if len(paths) > 1:
            for i, a in enumerate(group):
                for b in group[i + 1:]:
                    if a["relative_path"] == b["relative_path"]:
                        continue
                    edges.append(R.edge(
                        a["relative_path"], b["relative_path"], level="source",
                        hypotheses=[R.hypothesis(C.SRC_EXACT_FILE_DUPLICATE, 1.0,
                                                 [f"identical SHA-256 {sha[:16]}…"])],
                        evidence=["byte-identical files in different locations",
                                  "originals are never deleted, replaced or "
                                  "consolidated"],
                        confidence=1.0, sha256=sha))

    by_stem = defaultdict(list)
    by_folder = defaultdict(list)
    for s in sources:
        by_stem[normalize_stem(s["filename"])].append(s)
        by_folder[s["folder"]].append(s)

    for stem, group in by_stem.items():
        if len(group) < 2:
            continue
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                pc = _perceptual_corroboration(a, b)
                vis = bool(pc and pc["visually_near_identical"])
                ev = ["filename-normalized family"]
                hyps = [R.hypothesis(C.SRC_FILENAME_FAMILY, 0.6,
                                     [f"shared normalized stem {stem!r}"])]
                if a["format"] != b["format"]:
                    fmt_ev = [f"same stem carried as {a['format']} and "
                              f"{b['format']}",
                              "different formats have different editability; "
                              "technical readiness is NOT shared"]
                    if vis:
                        fmt_ev.append(
                            f"CORROBORATED VISUALLY: the whole sources are nearly "
                            f"identical (dHash {pc['dhash_distance']}, pHash "
                            f"{pc['phash_distance']})")
                    hyps.append(R.hypothesis(
                        C.SRC_ALTERNATE_FORMAT_SOURCE, 0.85 if vis else 0.6,
                        fmt_ev))
                if Path(a["filename"]).stem != Path(b["filename"]).stem:
                    hyps.append(R.hypothesis(
                        C.SRC_VERSION_SOURCE, 0.5,
                        [f"version/variant suffix differs: "
                         f"{Path(a['filename']).stem} vs "
                         f"{Path(b['filename']).stem}"]))
                if pc:
                    ev.append(
                        f"whole-source perceptual check: dHash "
                        f"{pc['dhash_distance']}, pHash {pc['phash_distance']} "
                        f"(transform {pc['best_transform']}) -> "
                        f"visually_near_identical={pc['visually_near_identical']}")
                    ev.append("this corroborates a SOURCE relationship only; it "
                              "does NOT make the candidates inside equivalent")
                edges.append(R.edge(a["relative_path"], b["relative_path"],
                                    level="source", hypotheses=hyps,
                                    evidence=ev,
                                    confidence=max(h["confidence"] for h in hyps),
                                    perceptual=pc))

    for folder, group in by_folder.items():
        if len(group) < 2:
            continue
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                edges.append(R.edge(
                    a["relative_path"], b["relative_path"], level="source",
                    hypotheses=[R.hypothesis(C.SRC_SAME_DOWNLOAD_PACKAGE, 0.4,
                                             [f"same folder/package: {folder}"])],
                    evidence=["package co-location is CONTEXT; it does not make "
                              "the candidates inside equivalent"],
                    confidence=0.4))
    return edges


# --- blocking: avoid naive all-pairs ---------------------------------------
def _bands(h: int, n_bands: int = 4, bits: int = 16) -> list[tuple[int, int]]:
    return [(i, (h >> (i * bits)) & ((1 << bits) - 1)) for i in range(n_bands)]


def candidate_blocks(cands: list[dict]) -> tuple[set[tuple[int, int]], dict]:
    """Generate plausible pairs by blocking. Returns (pairs, stats)."""
    pairs: set[tuple[int, int]] = set()
    buckets: dict[str, dict] = {"sha": defaultdict(list), "band": defaultdict(list),
                                "stem": defaultdict(list),
                                "folder": defaultdict(list),
                                "aspect_fmt": defaultdict(list)}

    for i, c in enumerate(cands):
        if c.get("source_sha256"):
            buckets["sha"][c["source_sha256"]].append(i)
        buckets["stem"][normalize_stem(c["filename_stem"])].append(i)
        buckets["folder"][c["source_folder"]].append(i)
        h = c.get("hash")
        if h:
            for band in _bands(h["phash"]):
                buckets["band"][band].append(i)
            ar = h["aspect_ratio"] or 1.0
            buckets["aspect_fmt"][(round(ar, 1), c["source_format"])].append(i)

    # A bucket above the safety limit is SKIPPED — and recorded. Skipping is a
    # documented scalability limitation, never a silent one: the pairs inside such
    # a bucket are simply not generated from that index, so the relationship search
    # must NOT be described as complete at full-library scale.
    skipped = []
    for kind, groups in buckets.items():
        for key, members in groups.items():
            if len(members) < 2:
                continue
            if len(members) > C.MAX_BUCKET_MEMBERS:
                missed = len(members) * (len(members) - 1) // 2
                skipped.append({"bucket_kind": kind, "bucket_key": str(key),
                                "members": len(members),
                                "pairs_not_generated_from_this_bucket": missed})
                continue
            for i, a in enumerate(members):
                for b in members[i + 1:]:
                    pairs.add((min(a, b), max(a, b)))

    n = len(cands)
    naive = n * (n - 1) // 2
    stats = {"candidates": n, "naive_pairs": naive,
             "blocked_pairs": len(pairs),
             "reduction": (round(1 - len(pairs) / naive, 4) if naive else 0.0),
             "buckets": {k: len(v) for k, v in buckets.items()},
             "max_bucket_members": C.MAX_BUCKET_MEMBERS,
             "skipped_buckets": skipped,
             "skipped_bucket_count": len(skipped),
             "coverage_note": (
                 "complete for this pilot (no bucket exceeded the limit)"
                 if not skipped else
                 f"INCOMPLETE: {len(skipped)} bucket(s) exceeded "
                 f"{C.MAX_BUCKET_MEMBERS} members and were skipped; members of "
                 "those buckets were compared only via the OTHER indexes (e.g. "
                 "pHash bands), so the relationship search is not exhaustive"),
             "strategy": ["exact-SHA groups", "pHash 4x16-bit bands",
                          "filename-normalized stems", "folder/package groups",
                          "aspect-ratio + format buckets"]}
    return pairs, stats


# --- graph, components, weak bridges ---------------------------------------
def build_components(node_ids: list[str], edges: list[dict]) -> dict:
    """Components from STRONG edges only, then split at weak bridges."""
    strong = [e for e in edges if e["confidence"] >= C.STRONG_EDGE_CONFIDENCE]
    adj = defaultdict(set)
    for e in strong:
        adj[e["a"]].add(e["b"])
        adj[e["b"]].add(e["a"])

    bridges = _find_bridges(adj)
    weak_bridges = []
    kept = []
    for e in strong:
        pair = frozenset((e["a"], e["b"]))
        if pair in bridges and e["confidence"] < C.WEAK_BRIDGE_CONFIDENCE:
            weak_bridges.append({
                "a": e["a"], "b": e["b"], "confidence": e["confidence"],
                "primary": e["primary"],
                "action": "COMPONENT_SPLIT",
                "reason": ("sole connector between two halves of a component and "
                           f"confidence {e['confidence']} < "
                           f"{C.WEAK_BRIDGE_CONFIDENCE}; splitting here prevents "
                           "A~B~C from silently fusing unrelated assets"),
                "human_confirmed": None,
            })
        else:
            kept.append(e)

    adj2 = defaultdict(set)
    for e in kept:
        adj2[e["a"]].add(e["b"])
        adj2[e["b"]].add(e["a"])

    seen, comps = set(), []
    for n in node_ids:
        if n in seen:
            continue
        stack, comp = [n], []
        seen.add(n)
        while stack:
            cur = stack.pop()
            comp.append(cur)
            for nb in adj2[cur]:
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        if len(comp) > 1:
            comps.append(sorted(comp))
    return {"components": comps, "weak_bridges": weak_bridges,
            "strong_edges": len(strong), "edges_after_split": len(kept),
            "note": "components are DERIVED for review convenience; the edges "
                    "remain authoritative and are never collapsed away"}


def _find_bridges(adj: dict) -> set[frozenset]:
    """Edges whose removal disconnects the graph (iterative Tarjan)."""
    disc, low, bridges = {}, {}, set()
    timer = [0]
    for root in list(adj):
        if root in disc:
            continue
        stack = [(root, None, iter(adj[root]))]
        disc[root] = low[root] = timer[0]
        timer[0] += 1
        while stack:
            node, parent, it = stack[-1]
            advanced = False
            for nb in it:
                if nb == parent:
                    continue
                if nb not in disc:
                    disc[nb] = low[nb] = timer[0]
                    timer[0] += 1
                    stack.append((nb, node, iter(adj[nb])))
                    advanced = True
                    break
                low[node] = min(low[node], disc[nb])
            if not advanced:
                stack.pop()
                if stack:
                    p = stack[-1][0]
                    low[p] = min(low[p], low[node])
                    if low[node] > disc[p]:
                        bridges.add(frozenset((p, node)))
    return bridges
